// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 x) internal {
        x = bound(x, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(x > 0);
        vm.assume(address(this).balance >= x);
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustBetAmounts(x) {} catch { return; }
        bool wagerReverted;
        try c.wager{value: x}() { wagerReverted = false; } catch { wagerReverted = true; }
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.play() { reverted = false; } catch { reverted = true; }
        assertTrue(reverted && address(c).balance == balBefore);
    }

    function testFuzz_run(uint256 x) public {
        _run(x);
    }

    receive() external payable {}
}
